use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut lefts: Vec<int> = []
    let mut rights: Vec<int> = []
    let mut root: int = -1
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse().unwrap_or(0)
            if root < 0 {
                keys.push(x)
                lefts.push(-1)
                rights.push(-1)
                root = 0
                println("ok")
            } else {
                let mut cur: int = root
                let mut done = false
                while !done {
                    let k = keys[cur as usize]
                    if x == k {
                        println("dup")
                        done = true
                    } else if x < k {
                        let l = lefts[cur as usize]
                        if l < 0 {
                            let idx: int = keys.len() as int
                            keys.push(x)
                            lefts.push(-1)
                            rights.push(-1)
                            lefts[cur as usize] = idx
                            println("ok")
                            done = true
                        } else {
                            cur = l
                        }
                    } else {
                        let r = rights[cur as usize]
                        if r < 0 {
                            let idx: int = keys.len() as int
                            keys.push(x)
                            lefts.push(-1)
                            rights.push(-1)
                            rights[cur as usize] = idx
                            println("ok")
                            done = true
                        } else {
                            cur = r
                        }
                    }
                }
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse().unwrap_or(0)
            let mut cur: int = root
            let mut found = false
            while cur >= 0 && !found {
                let k = keys[cur as usize]
                if x == k {
                    found = true
                } else if x < k {
                    cur = lefts[cur as usize]
                } else {
                    cur = rights[cur as usize]
                }
            }
            if found {
                println("yes")
            } else {
                println("no")
            }
        } else if cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            let mut cur: int = root
            let mut par: int = -1
            let mut found = false
            while cur >= 0 && !found {
                let k = keys[cur as usize]
                if x == k {
                    found = true
                } else {
                    par = cur
                    if x < k {
                        cur = lefts[cur as usize]
                    } else {
                        cur = rights[cur as usize]
                    }
                }
            }
            if !found {
                println("missing")
            } else {
                let l = lefts[cur as usize]
                let r = rights[cur as usize]
                if l >= 0 && r >= 0 {
                    let mut sp: int = cur
                    let mut s: int = r
                    while lefts[s as usize] >= 0 {
                        sp = s
                        s = lefts[s as usize]
                    }
                    keys[cur as usize] = keys[s as usize]
                    let sr = rights[s as usize]
                    if sp == cur {
                        rights[sp as usize] = sr
                    } else {
                        lefts[sp as usize] = sr
                    }
                } else {
                    let child: int = if l >= 0 { l } else { r }
                    if par < 0 {
                        root = child
                    } else if lefts[par as usize] == cur {
                        lefts[par as usize] = child
                    } else {
                        rights[par as usize] = child
                    }
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            if root < 0 {
                println("<empty>")
            } else {
                let mut out: Vec<string> = []
                let mut stack: Vec<int> = []
                let mut cur: int = root
                while cur >= 0 || stack.len() > 0 {
                    while cur >= 0 {
                        stack.push(cur)
                        cur = lefts[cur as usize]
                    }
                    let n = stack.pop().unwrap_or(0)
                    out.push("${keys[n as usize]}")
                    cur = rights[n as usize]
                }
                println(out.join(" "))
            }
        } else if cmd == "height" {
            let mut h: int = 0
            if root >= 0 {
                let mut level: Vec<int> = [root]
                while level.len() > 0 {
                    h = h + 1
                    let mut next: Vec<int> = []
                    for n in level {
                        let l = lefts[n as usize]
                        let r = rights[n as usize]
                        if l >= 0 {
                            next.push(l)
                        }
                        if r >= 0 {
                            next.push(r)
                        }
                    }
                    level = next
                }
            }
            println("${h}")
        } else if cmd == "min" {
            if root < 0 {
                println("empty")
            } else {
                let mut cur: int = root
                while lefts[cur as usize] >= 0 {
                    cur = lefts[cur as usize]
                }
                println("${keys[cur as usize]}")
            }
        } else if cmd == "max" {
            if root < 0 {
                println("empty")
            } else {
                let mut cur: int = root
                while rights[cur as usize] >= 0 {
                    cur = rights[cur as usize]
                }
                println("${keys[cur as usize]}")
            }
        }
    }
}

